var dataPoints = [];

// Capturamos el voltaje global del nodo
var voltage = parseFloat(inputData.vcc) || 0.0;

// Función auxiliar para crear el objeto de dato
function createPoint(sensorCode, d) {
    return {
        measurement: 'vibration_sensor', // Seguimos usando la misma tabla
        tags: {
            client: clientName,
            location: locationName,
            node: nodeId,
            sensor: sensorCode,
            redSSID: ssid,        // <--- NUEVO TAG: Tu red WiFi (PAPETTI)
            hw_ver: '1.5',
