        },
        fields: {
            ax: parseFloat(d.ax),
            ay: parseFloat(d.ay),
            az: parseFloat(d.az),
            mag_acc: parseFloat(Math.sqrt(d.ax*d.ax + d.ay*d.ay + d.az*d.az).toFixed(4)),

            // <--- AQUÍ ESTÁ LA MAGIA: Agregamos el voltaje como dato
            vcc: voltage 
        },
        timestamp: Date.now()
    };
}

// Procesamos s1 y s2 si existen
if (inputData.s1) dataPoints.push(createPoint("s1", inputData.s1));
if (inputData.s2) dataPoints.push(createPoint("s2", inputData.s2));

// Si no hay datos validos, salir
if (dataPoints.length === 0) return null;

// --- 5. SALIDA FINAL ---
msg.payload = {
    bucket: 'Vibranet_data', 
    precision: 'ms',         
    data: dataPoints         
};

return msg;

// CONFIGURACIÓN
var WINDOW_SIZE = 50; 
var G_TO_MM_S2 = 9806.65;
var NOISE_THRESHOLD = 0.05;

var bufferState = flow.get('sensorBuffer') || {}; 

// ... [MANTENER LA FUNCIÓN calculateComplexMetrics EXACTAMENTE IGUAL] ...
// ... (No la copio aquí para ahorrar espacio, pero NO la borres) ...

// --- LOGICA PRINCIPAL SIMPLIFICADA ---
var inputData = msg.payload;
// Ya no necesitamos parsear ni validar ID, el nodo anterior ya lo hizo.

// Leemos los metadatos que nos preparó el nodo anterior
var meta = inputData.meta; 
if (!meta) return null; // Por seguridad extra

var nodeId = meta.node;

// Inicializar buffers (Igual que antes)
if (!bufferState[nodeId]) {
    bufferState[nodeId] = { s1_ax:[], s1_ay:[], s1_az:[], s2_ax:[], s2_ay:[], s2_az:[], startTime: Date.now(), count: 0 };
}
var buf = bufferState[nodeId];

// Llenar datos (Igual que antes)
if (inputData.s1) { buf.s1_ax.push(parseFloat(inputData.s1.ax)); buf.s1_ay.push(parseFloat(inputData.s1.ay)); buf.s1_az.push(parseFloat(inputData.s1.az)); }
if (inputData.s2) { buf.s2_ax.push(parseFloat(inputData.s2.ax)); buf.s2_ay.push(parseFloat(inputData.s2.ay)); buf.s2_az.push(parseFloat(inputData.s2.az)); }

buf.count++;

if (buf.count >= WINDOW_SIZE) {
    var endTime = Date.now();
    var duration = (endTime - buf.startTime) / 1000; 
    if (duration <= 0) duration = 0.05; 
