        var vel_mag = Math.sqrt(mX.velocity_mm_s*mX.velocity_mm_s + mY.velocity_mm_s*mY.velocity_mm_s + mZ.velocity_mm_s*mZ.velocity_mm_s).toFixed(4);

        dataPoints.push({
