                rms_y: mY.rms, peak_y: mY.peak, crest_y: mY.crest, kurt_y: mY.kurtosis, vel_y: mY.velocity_mm_s,
                rms_z: mZ.rms, peak_z: mZ.peak, crest_z: mZ.crest, kurt_z: mZ.kurtosis, vel_z: mZ.velocity_mm_s,
                vel_mag: parseFloat(vel_mag)
            },
            timestamp: endTime
        });
    }

    // ... [Repetir lógica para S2 usando meta.client y meta.location] ...
