    bufferState[nodeId] = { s1_ax:[], s1_ay:[], s1_az:[], s2_ax:[], s2_ay:[], s2_az:[], startTime: Date.now(), count: 0 };
    flow.set('sensorBuffer', bufferState); 

    msg.payload = { bucket: 'Vibranet_data', precision: 'ms', data: dataPoints };
    return msg;
} else {
    flow.set('sensorBuffer', bufferState);
    return null; 
}

// Recibe el payload del heartbeat del ESP
var msgData = msg.payload;

// Validación básica
if (typeof msgData === "string") {
    try { msgData = JSON.parse(msgData); } catch(e) { return null; }
