var nodeId = msgData.id || "unknown";

// --- 1. CONTEXTO (Cliente/Ubicación) ---
var nodeId = msgData.id || "unknown"; // Asegúrate de leer el ID correcto

// --- LÓGICA DE ASIGNACIÓN (V6.1) ---
var clientName = "Desconocido";
var locationName = "Desconocida";

if (nodeId === "dango_node_001" || nodeId === "dango_node_002" || nodeId === "Telescopio_01") {
    // --- CASO OBSERVATORIO ---
