}

// --- 2. PREPARAR DATOS PARA INFLUXDB ---
var dataPoint = {
    measurement: "device_status", // <--- TABLA NUEVA
    tags: {
        node: nodeId,
        client: clientName,
        location: locationName,
        // Guardamos estos como TAGS para poder usarlos en las Variables de Grafana
        ssid: msgData.ssid || "Ethernet/Unknown",
