    },
    fields: {
        // Métricas numéricas
        vcc: parseFloat(msgData.bat) || 0,
        rssi: parseInt(msgData.rssi) || 0,
        ip: msgData.ip || "0.0.0.0",
        // Guardamos también la config actual para historial
        conf_mode: parseInt(msgData.conf ? msgData.conf.mode : -1),
        conf_sleep: parseInt(msgData.conf ? msgData.conf.sleep : -1)
    },
    timestamp: Date.now()
};

// Formato Stackhero InfluxDB v2
msg.payload = {
    bucket: 'Vibranet_data',
    precision: 'ms',
    data: [ dataPoint ]
};

return msg;

// ==========================================
// CONFIGURACIÓN
// ==========================================
var G_TO_MM_S2 = 9806.65;
var NOISE_THRESHOLD = 0.05; // <--- UMBRAL DE SILENCIO (en G)

// ==========================================
// FUNCIÓN MATEMÁTICA 
// ==========================================
function analyzeAxis(arr, fs) {
    if (!arr || arr.length === 0) return { rms: 0, peak: 0, crest: 0, kurt: 0, vel: 0 };

    var n = arr.length;
    var dt = 1.0 / fs;

    // 1. Estadísticas Básicas
    var min = Infinity, max = -Infinity, sum = 0;
    for (var i = 0; i < n; i++) {
        if (arr[i] < min) min = arr[i];
        if (arr[i] > max) max = arr[i];
        sum += arr[i];
    }
    var mean = sum / n;

    // 2. Momentos Estadísticos
    var sumSqDiff = 0;
    var sum4thDiff = 0;

    for (var i = 0; i < n; i++) {
        var diff = arr[i] - mean;
        var sq = diff * diff;
        sumSqDiff += sq;
        sum4thDiff += sq * sq;
    }

    var variance = sumSqDiff / n;
    var rms = Math.sqrt((sumSqDiff / n) + (mean * mean));
    var rms_ac = Math.sqrt(variance); // Vibración pura (sin DC)

    // --- COMPUERTA DE RUIDO ---
    if (rms_ac < NOISE_THRESHOLD) {
        return {
            rms: parseFloat(rms.toFixed(4)), // Mantenemos RMS para ver "vida"
            peak: 0,
            crest: 0,
            kurt: 0,
            vel: 0
        };
    }

    var kurtosis = 0;
    if (variance !== 0) kurtosis = (sum4thDiff / n) / (variance * variance);

    var peak = Math.max(Math.abs(min), Math.abs(max));
    var crest = (rms !== 0) ? (peak / rms) : 0;

    // 3. VELOCIDAD 
    var velocitySumSq = 0;
    var currentVel = 0;

    for (var i = 0; i < n - 1; i++) {
        var a1 = arr[i] - mean;
        var a2 = arr[i + 1] - mean;
        var area = ((a1 + a2) / 2) * dt * G_TO_MM_S2;
        currentVel += area;
        currentVel *= 0.995;
        velocitySumSq += currentVel * currentVel;
    }

    var velocityRMS = Math.sqrt(velocitySumSq / (n - 1));

    return {
        rms: parseFloat(rms.toFixed(4)),
        peak: parseFloat(peak.toFixed(4)),
        crest: parseFloat(crest.toFixed(4)),
        kurt: parseFloat(kurtosis.toFixed(4)),
        vel: parseFloat(velocityRMS.toFixed(4))
    };
}

// ==========================================
// PROCESAMIENTO PRINCIPAL
// ==========================================
var input = msg.payload;

if (!input || !input.dx || !input.fs) return null;


// --- EJECUTAR ANÁLISIS ---
var fs = input.fs;
var sX = analyzeAxis(input.dx, fs);
var sY = analyzeAxis(input.dy, fs);
var sZ = analyzeAxis(input.dz, fs);

var vel_mag = Math.sqrt(sX.vel * sX.vel + sY.vel * sY.vel + sZ.vel * sZ.vel);

var inputData = msg.payload;
var NOISE_THRESHOLD = 0.1; 

// Validaciones básicas de estructura
if (!inputData.dx || !Array.isArray(inputData.dx)) return null;

// LEEMOS METADATOS (Ya vienen listos)
var meta = inputData.meta;
if (!meta) return null;

// ==========================================
// SALIDA INFLUXDB 
// ==========================================
var dataPoint = {
    measurement: 'vibration_analysis',
    tags: {
        node: meta.node,          // <--- DEL META
        sensor: meta.sensor,      // <--- DEL META
        client: meta.client,      // <--- DEL META
        location: meta.location,  // <--- DEL META
        type: "advanced_stats"
    },
    fields: {
        rms_x: sX.rms, peak_x: sX.peak, crest_x: sX.crest, kurt_x: sX.kurt, vel_x: sX.vel,
        rms_y: sY.rms, peak_y: sY.peak, crest_y: sY.crest, kurt_y: sY.kurt, vel_y: sY.vel,
        rms_z: sZ.rms, peak_z: sZ.peak, crest_z: sZ.crest, kurt_z: sZ.kurt, vel_z: sZ.vel,
        vel_mag: parseFloat(vel_mag.toFixed(4))
    },
    timestamp: Date.now()
};

msg.payload = {
    bucket: 'Vibranet_data',
    precision: 'ms',
    data: [dataPoint]
};

return msg;

// === CONFIGURACIÓN DE LA FLOTA ===
var fleet = [
    { id: "Industria_Node_01", ip: "10.0.0.101", ver: "2.1" },
    { id: "Industria_Node_02", ip: "10.0.0.102", ver: "2.1" },
    { id: "Industria_Node_03", ip: "10.0.0.103", ver: "1.0" } // Versión vieja
];

// Generamos status para TODOS los nodos en un bucle (o uno al azar)
// Aquí enviamos uno al azar para no saturar el debug
var nodeVibranet = fleet[Math.floor(Math.random() * fleet.length)];

msg.payload = {
    id: nodeVibranet.id,
    t: "status",
    reason: "simulated_heartbeat",
    bat: (3 + Math.random() * 2).toFixed(2), // 
    ip: nodeVibranet.ip,
    rssi: -50 - Math.floor(Math.random() * 20),
    ssid: "WIFI_INDUSTRIAL_ACME",
    hw: "2.0",
    sw: nodeVibranet.ver,
    conf: {
        mode: 1, // Burst
        sleep: 0,
        thr: 5,
        freq: 500
    }
};

msg.topic = "vibranet/status/" + nodeVibranet.id;

return msg;

// === SIMULADOR MULTI-SENSOR ACADÉMICO ===
// Genera datos para s1 (Desbalanceo) y s2 (Desalineación)

var fs = 500; // Frecuencia de muestreo
var N = 256;  
var f_base = 50.0; // 3000 RPM

// Función para generar una señal vibratoria
function generateVibration(sensorName, amps) {
    var dx = [], dy = [], dz = [];

    // amps = [Amplitud 1x, Amplitud 2x, Amplitud 3x]
    var A1 = amps[0]; 
    var A2 = amps[1]; 
    var A3 = amps[2];

    for (var i = 0; i < N; i++) {
        var t = i * (1/fs);

        // EJE X: Señal Compleja
        var val_x = (A1 * Math.sin(2 * Math.PI * f_base * t)) + 
                    (A2 * Math.sin(2 * Math.PI * (2 * f_base) * t)) +
                    (A3 * Math.sin(2 * Math.PI * (3 * f_base) * t)) +
                    (Math.random() * 0.1);
        dx.push(val_x);

        // Ejes Y/Z (Relleno simple)
        dy.push(0.5 * Math.sin(2 * Math.PI * f_base * t));
        dz.push(9.81 + (0.2 * Math.sin(2 * Math.PI * 120 * t))); // Gravedad + ruido
    }

    return {
        payload: {
            id: "Industria_Node_01",
            s: sensorName, // <--- AQUÍ CAMBIA EL NOMBRE DINÁMICAMENTE
            t: "burst",
            fs: fs,
            dx: dx, dy: dy, dz: dz
        }
    };
}

// --- ESCENARIOS FÍSICOS ---

// SENSOR 1: Desbalanceo Puro (Dominancia de 1x)
// 1x = 2.0 (Alto), 2x = 0.2 (Bajo), 3x = 0.1 (Bajo)
var msg1 = generateVibration("s1", [2.0, 0.2, 0.1]);

// SENSOR 2: Desalineación Severa (Dominancia de 2x)
// 1x = 0.8 (Medio), 2x = 1.8 (Muy Alto), 3x = 0.5 (Medio)
var msg2 = generateVibration("s2", [0.8, 1.8, 0.5]);

// Enviar ambos mensajes al flujo
return [[msg1, msg2]];

// ==========================================
// 1. FILTRO Y CONTEXTO
// ==========================================
var inputData = msg.payload;

// Umbral de silencio en G (Ahora que normalizamos, 0.08 es muy preciso)
var NOISE_THRESHOLD = 0.08; 

// Validaciones
if (typeof inputData === "string") {
    try { inputData = JSON.parse(inputData); } catch (e) { return null; }
}

// Leemos Metadatos del nodo "Asignar Contexto"
var meta = inputData.meta;
if (!meta) return null;

if (!inputData.dx || !Array.isArray(inputData.dx)) return null;

// ==========================================
// 2. MATEMÁTICA FFT (CORREGIDA Y NORMALIZADA)
// ==========================================

function runFFT(data) {
    var n = data.length;
    var sum = 0; 

    // 1. Calcular Media (DC Offset)
    for (var i = 0; i < n; i++) sum += data[i];
    var avg = sum / n;

    // 2. Preparar arrays complejos y quitar DC
    var re = new Array(n); 
    var im = new Array(n);
    for (var i = 0; i < n; i++) { 
        re[i] = data[i] - avg; 
        im[i] = 0.0; 
    }

    // 3. Algoritmo FFT (Cooley-Tukey)
    var j = 0;
    for (var i = 0; i < n - 1; i++) {
        if (i < j) {
            var tempRe = re[i]; re[i] = re[j]; re[j] = tempRe;
            var tempIm = im[i]; im[i] = im[j]; im[j] = tempIm;
        }
        var k = n >> 1;
        while (k <= j) { j -= k; k >>= 1; }
        j += k;
    }

    var m = Math.log2(n);
    var le, le2, ur, ui, sr, si, tr, ti, ip;

    for (var l = 1; l <= m; l++) {
        le = 1 << l; le2 = le >> 1;
        ur = 1.0; ui = 0.0;
        sr = Math.cos(Math.PI / le2); si = -Math.sin(Math.PI / le2);

        for (j = 0; j < le2; j++) {
            for (var i = j; i < n; i += le) {
                ip = i + le2;
                tr = re[ip] * ur - im[ip] * ui;
                ti = re[ip] * ui + im[ip] * ur;
                re[ip] = re[i] - tr; im[ip] = im[i] - ti;
                re[i] = re[i] + tr; im[i] = im[i] + ti;
            }
            var temp = ur; ur = temp * sr - ui * si; ui = temp * si + ui * sr;
        }
    }

    // 4. CALCULO DE MAGNITUD CON NORMALIZACIÓN (EL FIX IMPORTANTE)
    // Multiplicamos por 2 y dividimos por N para obtener amplitud real
    var mags = [];
    var normalizationFactor = 2.0 / n;

    for (var i = 0; i < n / 2; i++) {
        var magnitude = Math.sqrt(re[i] * re[i] + im[i] * im[i]);
        mags.push(magnitude * normalizationFactor); 
    }
    return mags;
}

// Buscar pico más alto
function getPeak(mags, res) {
    var max = 0, freq = 0;
    // Empezamos en i=1 para ignorar residuales de DC muy bajos
    for (var i = 1; i < mags.length; i++) {
        if (mags[i] > max) { 
            max = mags[i]; 
            freq = i * res; 
        }
    }
    return { f: freq, m: max };
}

// Obtener magnitud de armónico específico
function getHarmonicMag(mags, targetFreq, res) {
    var index = Math.round(targetFreq / res);
    var maxVal = 0;
    var searchRadius = 2; // Buscar en bins vecinos por si no cae exacto

    for (var i = Math.max(0, index - searchRadius); i <= Math.min(mags.length - 1, index + searchRadius); i++) {
        if (mags[i] > maxVal) maxVal = mags[i];
    }
    return maxVal;
}

// Calcular RMS desde el dominio de la frecuencia (Teorema de Parseval aprox)
function getRMS_from_Spectrum(mags) {
    var sumSq = 0;
    // Para RMS desde espectro normalizado: sqrt(sum(Amp^2) / 2)
    // Pero como ya normalizamos por 2/N, usamos la suma directa de potencias ajustada
    for(var i=0; i<mags.length; i++) sumSq += (mags[i] * mags[i]);
    return Math.sqrt(sumSq / 2.0); 
}

// ==========================================
// 3. PROCESAMIENTO
// ==========================================
var fs = inputData.fs || 500;
var resolution = fs / inputData.dx.length;

// Ejecutar FFT (Ahora devuelve valores reales en G)
var mX = runFFT(inputData.dx);
var mY = runFFT(inputData.dy);
var mZ = runFFT(inputData.dz);

// Análisis General
var pX = getPeak(mX, resolution); var rX = getRMS_from_Spectrum(mX);
var pY = getPeak(mY, resolution); var rY = getRMS_from_Spectrum(mY);
var pZ = getPeak(mZ, resolution); var rZ = getRMS_from_Spectrum(mZ);

// Calculamos Energía Total (Vectorial)
var total_energy = Math.sqrt(rX*rX + rY*rY + rZ*rZ);

// --- VARIABLES DE SALIDA ---
var h1_x = 0, h2_x = 0, h3_x = 0;
var FUNDAMENTAL_HZ = 50.0;

// ==========================================
// 4. COMPUERTA DE RUIDO (NOISE GATE)
// ==========================================

// Debug para que veas el valor real en la consola de debug
node.warn("Sensor: " + meta.sensor + " | Total RMS: " + total_energy.toFixed(4) + "g");

if (total_energy < NOISE_THRESHOLD) {
    // ESTADO: QUIETO -> Limpieza total
    pX.f = 0; pX.m = 0;
    pY.f = 0; pY.m = 0;
    pZ.f = 0; pZ.m = 0;

    // Forzamos RMS a 0 en graficos de frecuencia para limpieza visual
    // (En graficos de tiempo se verán los valores residuales reales)
    rX = 0; rY = 0; rZ = 0;
    total_energy = 0; 

    h1_x = 0; h2_x = 0; h3_x = 0;

} else {
    // ESTADO: VIBRANDO -> Calcular Armónicos
    h1_x = getHarmonicMag(mX, FUNDAMENTAL_HZ, resolution);
    h2_x = getHarmonicMag(mX, FUNDAMENTAL_HZ * 2, resolution);
    h3_x = getHarmonicMag(mX, FUNDAMENTAL_HZ * 3, resolution);
}

// ==========================================
// 5. SALIDA
// ==========================================
var dataPoint = {
    measurement: "vibration_triaxial",
    tags: {
        node: meta.node,
        sensor: meta.sensor,
        client: meta.client,
        location: meta.location,
        mode: "burst_fft"
    },
    fields: {
        // Datos Generales
        x_peak_hz: Number(pX.f.toFixed(2)), x_peak_mag: Number(pX.m.toFixed(4)), x_rms: Number(rX.toFixed(4)),
        y_peak_hz: Number(pY.f.toFixed(2)), y_peak_mag: Number(pY.m.toFixed(4)), y_rms: Number(rY.toFixed(4)),
        z_peak_hz: Number(pZ.f.toFixed(2)), z_peak_mag: Number(pZ.m.toFixed(4)), z_rms: Number(rZ.toFixed(4)),
        total_vibration: Number(total_energy.toFixed(4)),

        // Armónicos
        mag_1x: Number(h1_x.toFixed(4)), 
        mag_2x: Number(h2_x.toFixed(4)), 
        mag_3x: Number(h3_x.toFixed(4))  
    },
    timestamp: Date.now()
};

msg.payload = {
    bucket: 'Vibranet_data',
    precision: 'ms',
    data: [dataPoint]
};

return msg;

// 1. PARSEO SEGURO
var input = msg.payload;
if (typeof input === "string") {
